// Terser, not UglifyJS 2: that one only parses ES5, so no code of the client
// could use anything newer (const, arrow functions, async, classes, ?.)
var terser = require("terser");
var transform = require("./transform").transform;
var fs = require("fs");

function compress(sources, opts) {
    if (!opts)
        opts = {};
    if (typeof sources == "string")
        sources = [{source: sources, file: ""}];
    
    var files = {};
    var count = 0;
    var literals = [];
    
    sources.forEach(function(pkg) {
        if (pkg.source == undefined && pkg.file)
            pkg.source = fs.readFileSync(pkg.file, "utf8");
        
        if (/"disable compress"/.test(pkg.source))
            return literals.push(pkg.source);
        
        var source = pkg.source;
        try {
            source = transform(source, { mode: "es5" });
        } catch(e) {
            logParseError(e, pkg);
            throw e;
        }
        var name = (pkg.file || pkg.id || "").replace(new RegExp("^" + opts.basepath + "/"), ""); //@todo remove prefix
        // (one name for each: sources without one, or with the same)
        files[count++ + ":" + name] = source;
        pkg.$name = count - 1 + ":" + name;
    });
    
    if (!count) {
        return { code: literals.join("\n"), map: null };
    }
    
    if (opts.compress == "dryrun") {
        return { code: "dryrun\n" };
    }
    
    var options = {
        // what the code is written in: nothing is turned into older syntax,
        // and the compressor doesn't make newer syntax of it either
        ecma: 5,
        // the client is many scripts that share the global scope
        toplevel: false,
        compress: {
            unsafe: false,
            // (the module loader reads the parameters of define()'s function)
            keep_fargs: true,
            warnings: !!opts.verbose
        },
        // Right now this breaks the LogicBlox workspace; needs further investigation
        mangle: opts.obfuscate
            ? { reserved: ["$", "require", "exports", "initBaseUrls", "initSender"] }
            : false,
        format: opts.oneLine ? {} : {
            quote_keys: false,    // quote all keys in object literals?
            ascii_only: false,    // output ASCII-safe? (encodes Unicode characters as ASCII)
            inline_script: false, // escape "</script"?
            max_line_len: 100,    // maximum line length (for non-beautified output)
            beautify: false,      // beautify output?
            braces: false,        // use brackets every time?
            comments: false,      // output comments?
            semicolons: false     // use semicolons to separate statements? (otherwise, newlines)
        }
    };
    delete options.compress.warnings;
    
    if (opts.mapFile) {
        // Generate a source map
        options.sourceMap = {
            filename: opts.mapFile || "build.js.map",
            root: opts.mapRoot
        };
    }
    
    var result;
    try {
        result = terser.minify_sync(files, options);
    } catch (e) {
        // (terser says which file: "<number>:<name>")
        var pkg = sources.filter(function(pkg) { return pkg.$name == e.filename; })[0];
        logParseError(e, pkg || sources[0]);
        throw e;
    }
    
    function asciify(text) {
        // remove top level use strict since that can break some librarires
        text = text.replace(/^(["'])use strict\1/, "$1no strict!$1");
        text = text.replace(/[\x80-\uffff]/g, function(c) {
            c = c.charCodeAt(0).toString(16);
            if (c.length == 2)
                return "\\x" + c;
            if (c.length == 3)
                c = "0" + c;
            return "\\u" + c;
        });
        return text;
    }
    
    return {
        code : asciify(result.code) + "\n" + literals.join("\n"),
        map  : result.map || null // json output for your source map
    };
}

function logParseError(e, pkg) {
    console.error("Error while parsing", (pkg.file || pkg.id) + ":" + e.line + ":" + e.col);
    if (e.line) {
        var MAX_LEN = 45;
        var line = pkg.source.split("\n")[e.line - 1];
        var col = e.col;
        if (col > MAX_LEN) {
            line = line.slice(col - MAX_LEN);
            col = MAX_LEN;
        }
        if (line.length > col + MAX_LEN)
            line = line.slice(0, col + MAX_LEN);
        line = line + "\n" + Array(col + 1).join(" ") + "^";
        console.error(line);
    }
}

compress.withCache = function(sources, opts) {
    var cache = opts.cache || {};
    if (cache && !cache.compress)
        cache.compress = Object.create(null);
    if (typeof sources == "string")
        sources = [{source: sources, file: ""}];
    var code = sources.map(function(pkg) {
        if (pkg.id && cache.compress[pkg.id]) {
            // console.log("Compress Cache Hit " + pkg.id);
            return cache.compress[pkg.id];
        }
        if (opts.exclude && opts.exclude.test(pkg.id))
            return pkg.source;
        var code = compress([pkg], opts).code;
        if (/[([]/.test(code[0]))
            code = ";" + code;
        return (cache.compress[pkg.id] = code);
    }).join("\n");
    return {code: code, map: null};
};

module.exports = compress;


